GLOSSARY += [
('CPU', 'Central processing unit — центральный процессор. CPU seconds измеряют использованную процессорную работу, wall time также включает ожидание.'),
('RAM', 'Random-access memory — оперативная память. Рост числа workers может увеличить память controller и привести к вытеснению/ошибкам вместо ускорения.'),
('ICMP', 'Internet Control Message Protocol — протокол служебных сообщений IP. Ansible ping исполняет модуль и не является ICMP echo.'),
('TCP', 'Transmission Control Protocol — транспорт над IP с упорядоченным потоком байтов. SSH обычно использует TCP, но успешный TCP-connect не доказывает аутентификацию и исполнение модуля.'),
('UTF-8', 'Кодировка Unicode переменной длины для представления текста байтами. Смена представления/newline меняет точный checksum файла.'),
]


def flag(name, action, when, example, result):
    return dict(flag=name, action=action, when=when, example=example, result=result)


def command(name, purpose, syntax, chapter, page, flags=(), situations=()):
    url = 'https://docs.ansible.com/projects/ansible/latest/' + page
    return dict(name=name, aliases=[], purpose=purpose, syntax=syntax,
                chapter=chapter, volume='ansible', source=url,
                sources=[dict(title='Официальная документация; сверено 01.11.2026, core 2.21.5', url=url)],
                flags=list(flags), situations=list(situations))

